'use strict';
const $=id=>document.getElementById(id);
const labels={confirmed:'漏洩を確認',possible:'漏洩の可能性',mixed:'確認済み・可能性あり',access:'権限外の閲覧を確認',denied:'続報で漏洩を否定',catalogue:'HIBP検証済み',announcement:'公式発表（自動取得・未整理）',needsReview:'出典更新あり・再確認待ち'};
const state={records:[],tab:'all',limit:8,saved:new Set(),storage:true};
async function loadUpdateStatus(){const target=$('updateStatus');if(!target)return;try{const response=await fetch('update-status.json',{cache:'no-cache'});if(!response.ok)throw new Error('Status unavailable');const x=await response.json();const date=x.lastAttemptAt?new Intl.DateTimeFormat('ja-JP',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tokyo'}).format(new Date(x.lastAttemptAt)):'未実行';const stale=x.lastAttemptAt&&(Date.now()-Date.parse(x.lastAttemptAt)>3*60*60*1000);target.textContent=(x.cloudRun?'前回のクラウド実行：':'クラウド自動実行は未接続。手動試行：')+date+' ／ '+(x.status==='complete'?'登録先の取得を完了':x.status==='partial'?'一部取得失敗（'+x.failedFetches+'件）':'情報取得に失敗')+'。'+(stale?'更新日時が古くなっています。':'')+'新着の自動取得と、対象条件の確認済み要約は区別しています。';}catch{target.textContent='自動更新の実行状況を取得できませんでした。掲載済みデータの確認日は別に表示しています。';}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFKC').toLocaleLowerCase('ja').trim();
const safeUrl=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:'#'}catch{return '#'}};
const displayDate=s=>s?s.replaceAll('-','.'):'未公表';
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2800)}
function getSaved(){try{const ids=JSON.parse(localStorage.getItem('mofu-leakcheck-saved')||'[]');if(Array.isArray(ids))state.saved=new Set(ids.filter(id=>typeof id==='string'&&state.records.some(r=>r.id===id)))}catch{state.storage=false}}
function save(id){if(!state.records.some(r=>r.id===id))return;if(state.saved.has(id)){state.saved.delete(id);toast('「あとで確認」から外しました')}else{state.saved.add(id);toast(state.storage?'「あとで確認」に保存しました':'この画面の「あとで確認」に追加しました')}try{localStorage.setItem('mofu-leakcheck-saved',JSON.stringify([...state.saved]))}catch{state.storage=false;toast('保存機能が制限されています。この画面を開いている間だけ保持します。')}render();const target=[...document.querySelectorAll('[data-save]')].find(x=>x.dataset.save===id);if(target)target.focus({preventScroll:true})}
function badge(r){return `<span class="badge ${esc(r.status)}">${esc(labels[r.status]||'出典を確認')}</span>`}
function card(r){const saved=state.saved.has(r.id);return `<article class="incident" aria-labelledby="title-${esc(r.id)}"><div class="incident-top"><div><div class="company-line"><h3 id="title-${esc(r.id)}">${esc(r.company)}</h3><span class="category-tag">${esc(r.category)}</span></div><p class="service-title">${esc(r.service)}</p></div><button class="bookmark ${saved?'saved':''}" data-save="${esc(r.id)}" aria-pressed="${saved}" aria-label="${esc(r.service)}を${saved?'あとで確認から外す':'あとで確認に保存'}"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5 2h10v16l-5-3-5 3Z"/></svg></button></div><div class="incident-sub">${badge(r)}<span class="source-date">${r.sourceType==='hibp'?`事例発生日 ${esc(displayDate(r.eventDate))} ・ 海外サービス`:`公表 ${esc(displayDate(r.published))}${r.updated!==r.published?` ・ 資料更新 ${esc(displayDate(r.updated))}`:''}`}</span></div><div class="impact-grid"><div class="audience"><span class="field-label">${r.status==='denied'?'続報の結論':'対象となる登録・利用（公表範囲）'}</span><p>${esc(r.audience)}</p></div><div class="data-block"><span class="field-label">${r.status==='denied'?'現在の公表状況':'公表資料に記載された情報項目'}</span><div class="tags">${r.items.length?r.items.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):`<span class="tag">${r.status==='denied'?'漏洩はなかったと判断した旨を公表':'情報項目は未確認。出典本文をご確認ください。'}</span>`}</div></div></div>${r.excluded?`<p class="exclude"><b>${r.status==='denied'?'訂正内容：':'対象外・補足：'}</b>${esc(r.excluded)}</p>`:''}<div class="incident-foot"><span>${r.automaticallyCollected?'公式ページを自動取得':r.sourceChanged?'出典の再確認が必要':'資料確認 '+esc(displayDate(r.verifiedAt))}</span><div class="actions"><button class="textbtn" data-detail="${esc(r.id)}">対象条件・詳細</button><a class="source-link" href="${esc(safeUrl(r.source))}" target="_blank" rel="noopener noreferrer">${r.sourceType==='hibp'?'出典：HIBP':'公式発表を読む'} ↗</a></div></div></article>`}
function filtered(){const words=norm($('query').value).split(/[\s、,]+/).filter(Boolean);return state.records.filter(r=>{if(state.tab==='saved'&&!state.saved.has(r.id))return false;if(['official','hibp'].includes(state.tab)&&r.sourceType!==state.tab)return false;if($('category').value!=='all'&&r.category!==$('category').value)return false;if($('status').value!=='all'&&r.status!==$('status').value)return false;if($('dataType').value!=='all'&&!r.items.join(' ').includes($('dataType').value))return false;const text=norm([r.company,r.service,r.aliases,r.audience,...r.items].join(' '));return words.every(w=>text.includes(w))}).sort((a,b)=>$('sort').value==='name'?a.company.localeCompare(b.company,'ja'):b.updated.localeCompare(a.updated)||a.company.localeCompare(b.company,'ja'))}
function render(){const rs=filtered();$('allCount').textContent=state.records.length;$('jpCount').textContent=state.records.filter(r=>r.sourceType==='official').length;$('globalCount').textContent=state.records.filter(r=>r.sourceType==='hibp').length;$('savedCount').textContent=state.saved.size;$('resultCount').textContent=`${rs.length}件の掲載情報${rs.length?' ・ '+Math.min(state.limit,rs.length)+'件を表示中':''}`;$('list').innerHTML=rs.slice(0,state.limit).map(card).join('');$('empty').hidden=rs.length>0;$('more').hidden=rs.length<=state.limit;$('more').textContent=`さらに表示する（残り${Math.max(0,rs.length-state.limit)}件）`;$('coverage').textContent=state.tab==='hibp'?'日本でも利用される海外の11サービスを選定。出典：Have I Been Pwned（CC BY 4.0）。日本の利用者の対象人数は確認できていません。':state.tab==='saved'?'保存されるのは事例のIDだけです。個人情報の漏洩判定をした結果ではありません。':'国内37社の公式発表を中心に掲載しています。すべての事故・企業を網羅した一覧ではありません。';document.querySelectorAll('[data-tab]').forEach(b=>{const on=b.dataset.tab===state.tab;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))})}
function reset(){state.tab='all';state.limit=8;['query'].forEach(id=>$(id).value='');['category','status','dataType'].forEach(id=>$(id).value='all');render()}
function detail(id,updateHash=true){const r=state.records.find(x=>x.id===id);if(!r)return;$('detailContent').innerHTML=`${badge(r)}<h2>${esc(r.company)}</h2><p>${esc(r.service)}</p><p class="detail-dates">${r.sourceType==='hibp'?`HIBPの事例発生日：${esc(displayDate(r.eventDate))} ／ HIBP収録日：${esc(displayDate(r.published))}`:`初回公表日：${esc(displayDate(r.published))} ／ 参照資料更新日：${esc(displayDate(r.updated))}`}<br>${r.automaticallyCollected?'自動取得の発表です。対象条件・要約は未確認。':r.sourceChanged?'旧要約の確認日：'+esc(displayDate(r.verifiedAt))+'（出典更新のため再確認待ち）':'資料確認日：'+esc(displayDate(r.verifiedAt))}</p><h3>どんな登録・利用が対象？</h3><p class="detail-scope">${esc(r.audience)}</p><h3>公表資料に記載された情報項目</h3><p>${r.items.map(esc).join('、')||(r.status==='denied'?'続報で漏洩はなかったと判断したとの報告を受けたと公表しています。':'この項目は確認していません。出典の本文をご確認ください。')}</p><h3>公表されている件数・範囲</h3><p>${esc(r.scale)}</p><p class="fine">件数・人数・アカウント数は出典の単位を保っています。項目や区分の件数を合算した被害人数には置き換えていません。</p><h3>確認されていること・留意する点</h3><p>${esc(r.note)}</p>${r.excluded?`<h3>対象外・補足</h3><p>${esc(r.excluded)}</p>`:''}<p class="facts">この事例の公表条件と、ご自身の登録・利用履歴を照らし合わせてください。個人の情報が実際に漏洩したかは、このサイトでは判定できません。</p><a class="source-link" href="${esc(safeUrl(r.source))}" target="_blank" rel="noopener noreferrer">${r.sourceType==='hibp'?'Have I Been Pwnedの事例ページを開く':'企業等の公式発表・案内を開く'} ↗</a>${(r.additionalSources||[]).map(u=>`<br><a class="source-link" href="${esc(safeUrl(u))}" target="_blank" rel="noopener noreferrer">あわせて参照した公式発表 ↗</a>`).join('')}${r.originalDescription?`<h3>出典の原文（英語）</h3><p class="original" lang="en">${esc(r.originalDescription)}</p><p class="fine">Data from <a href="https://haveibeenpwned.com/" target="_blank" rel="noopener noreferrer">Have I Been Pwned</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. 日本語の対象条件・情報項目はこのデータに基づく要約です。</p>`:''}`;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;if(updateHash)history.replaceState(null,'','#'+encodeURIComponent(id))}
async function load(){try{$('loadError').hidden=true;const response=await fetch('incidents.json',{cache:'no-cache'});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json();if(!Array.isArray(data.incidents))throw new Error('Invalid catalogue');state.records=data.incidents;const opts=[...new Set(state.records.map(x=>x.category))].sort((a,b)=>a.localeCompare(b,'ja'));$('category').innerHTML='<option value="all">すべてのジャンル</option>'+opts.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');getSaved();render();await loadUpdateStatus();if(location.hash){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{}if(id)detail(id,false)}}catch(err){$('list').innerHTML='';$('resultCount').textContent='一覧を表示できませんでした';$('loadError').hidden=false;$('more').hidden=true;console.error('Catalogue could not be loaded',err)}}
$('searchForm').addEventListener('submit',e=>{e.preventDefault();state.limit=8;render();$('results').scrollIntoView({behavior:'smooth'})});$('query').addEventListener('input',()=>{state.limit=8;render()});document.querySelectorAll('[data-query]').forEach(b=>b.addEventListener('click',()=>{reset();$('query').value=b.dataset.query;render();$('results').scrollIntoView({behavior:'smooth'})}));document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{state.tab=b.dataset.tab;state.limit=8;render()}));['category','status','dataType','sort'].forEach(id=>$(id).addEventListener('change',()=>{state.limit=8;render()}));$('reset').addEventListener('click',reset);$('emptyReset').addEventListener('click',reset);$('more').addEventListener('click',()=>{state.limit+=8;render()});$('retry').addEventListener('click',load);$('list').addEventListener('click',e=>{const b=e.target.closest('[data-detail],[data-save]');if(!b)return;if(b.dataset.detail)detail(b.dataset.detail);else if(b.dataset.save)save(b.dataset.save)});$('detail').querySelector('.close').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('close',()=>history.replaceState(null,'',location.pathname+location.search));$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const rect=$('detail').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('detail').close()}});window.addEventListener('hashchange',()=>{if(location.hash){try{detail(decodeURIComponent(location.hash.slice(1)),false)}catch{}}else if($('detail').open)$('detail').close()});load();
